export function resolveLandingPageAssetPath(assetBasePath: string | undefined, assetPath: string) {
  const normalizedBase = (assetBasePath ?? "").replace(/\/+$/, "");
  const normalizedAsset = assetPath.startsWith("/") ? assetPath : `/${assetPath}`;

  return normalizedBase ? `${normalizedBase}${normalizedAsset}` : normalizedAsset;
}
